# -*- coding: utf-8 -*-
"""
Maktab Boshqaruv Portali (Kundalik.com tizimi)
Istalgan kompyuterda Python orqali bir marta ishga tushirilsa yetarli.
Hech qanday qo'shimcha kutubxona o'rnatish shart emas (standart Python kutubxonalari).
"""

import os
import sys
import zlib
import base64
import socket
import webbrowser
import http.server
import socketserver

PORT = 8080
HTML_DATA = """"""

def setup_html():
    """Saytning to'liq index.html faylini avtomatik yaratadi"""
    html_content = zlib.decompress(base64.b64decode(HTML_DATA))
    with open('index.html', 'wb') as f:
        f.write(html_content)

def get_local_ip():
    """Wi-Fi yoki mahalliy tarmoqdagi IP manzilni aniqlaydi"""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(('8.8.8.8', 80))
        ip = s.getsockname()[0]
    except Exception:
        ip = '127.0.0.1'
    finally:
        s.close()
    return ip

def run_server():
    setup_html()
    local_ip = get_local_ip()

    class CustomHandler(http.server.SimpleHTTPRequestHandler):
        def log_message(self, format, *args):
            pass  # Konsolni ortiqcha loglar bilan to'ldirmaydi

    port = PORT
    httpd = None
    for attempt_port in range(port, port + 10):
        try:
            httpd = socketserver.TCPServer(('', attempt_port), CustomHandler)
            port = attempt_port
            break
        except OSError:
            continue

    if not httpd:
        print("[XATO] Portlar band qilingan, serverni yoqib bo'lmadi.")
        return

    print("=" * 60)
    print("   MAKTAB BOSHQARUV PORTALI MUVAFFAQIYATLI ISHGA TUSHDI!   ")
    print("=" * 60)
    print(f"Kompyuter (Noutbuk) orqali kirish havolasi:")
    print(f"   --> http://localhost:{port}/")
    print()
    print(f"Telefon orqali kirish havolasi (Wi-Fi tarmog'ida):")
    print(f"   --> http://{local_ip}:{port}/")
    print("=" * 60)
    print("Serverni to'xtatish uchun terminalda Ctrl + C tugmalarini bosing.")
    print("=" * 60)

    try:
        webbrowser.open(f"http://localhost:{port}/")
    except Exception:
        pass

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\n[INFO] Server to'xtatildi.")
        httpd.server_close()

if __name__ == '__main__':
    run_server()
